    InvalidAgeException(String message) { super(message); }
}
public class Main {
    public static void main(String[] args) {
        try { throw new InvalidAgeException("Age too low"); }
        catch (InvalidAgeException e) { System.out.println(e.getMessage()); }
    }
}
```

